// Browser stand-in for the extension host: applies captured theme variables,
// fakes acquireVsCodeApi and serves fixture data generated by data.ts.
// Query: ?theme=dark|light|high-contrast|high-contrast-light&repo=<scenario>&select=<row>&showStashes=0
//   &menu=<selector>: right-click that element, shown as while VS Code's menu is open
//   &busy=<label>: a Strata operation running
//   &banner=rebase|rebaseResolved|rebaseStopped|merge|mergeResolved|sequencer|leftover|leftoverResolved|pending|conflicts
import type { Commit } from '../src/core/commit.ts';
import type { Leftover, OperationState } from '../src/core/repo-state.ts';
import {
  DEFAULT_OPTIONS,
  type HostToWebview,
  type ThemeKind,
  type ViewOptions,
  type WebviewToHost,
} from '../src/shared/protocol.ts';
import dark from './themes/dark.json';
import highContrastLight from './themes/high-contrast-light.json';
import highContrast from './themes/high-contrast.json';
import light from './themes/light.json';
import type { PlaygroundData } from './types.ts';

const themes: Record<ThemeKind, Record<string, string>> = {
  dark,
  light,
  'high-contrast': highContrast,
  'high-contrast-light': highContrastLight,
};
const bodyClass: Record<ThemeKind, string[]> = {
  dark: ['vscode-dark'],
  light: ['vscode-light'],
  'high-contrast': ['vscode-high-contrast'],
  'high-contrast-light': ['vscode-high-contrast', 'vscode-high-contrast-light'],
};

const params = new URLSearchParams(location.search);
const theme = (params.get('theme') ?? 'dark') as ThemeKind;
const repo = params.get('repo') ?? 'branchy';
const selectRow = params.get('select');
/** `open=filter` opens the ref filter popover for screenshots. */
const openPopover = params.get('open');
const menuAt = params.get('menu');
const busy = params.get('busy');
const bannerState = params.get('banner');

for (const [k, v] of Object.entries(themes[theme])) document.documentElement.style.setProperty(k, v);
document.body.classList.add(...bodyClass[theme]);

const toWebview = (m: HostToWebview) => {
  window.postMessage(m, '*');
};

/** Messages the webview sent; read by scripts/playground-shot.mjs. */
const sent: WebviewToHost[] = [];
let data: PlaygroundData | undefined;
let offset = 0;
let generation = 1;
/** View options in the query win over those the webview restored. */
const queried: Partial<ViewOptions> = {
  ...(params.has('firstParent') ? { firstParent: params.get('firstParent') === '1' } : {}),
  ...(params.has('showStashes') ? { showStashes: params.get('showStashes') !== '0' } : {}),
};
let options: ViewOptions = { ...DEFAULT_OPTIONS, ...queried };
let visible: Commit[] = [];

/** Commits reachable from the selected refs (in the original order), like git log <refs> [--first-parent]. */
function select(d: PlaygroundData, o: ViewOptions): Commit[] {
  const byHash = new Map(d.commits.map((c) => [c.hash, c]));
  const starts = o.refs
    ? d.refs.refs.filter((r) => o.refs!.includes(r.name)).map((r) => r.hash)
    : [...d.refs.refs.map((r) => r.hash), ...(d.refs.head ? [d.refs.head] : [])];
  const seen = new Set<string>();
  const stack = [...starts];
  while (stack.length > 0) {
    const h = stack.pop()!;
    if (seen.has(h)) continue;
    seen.add(h);
    const c = byHash.get(h);
    if (c) stack.push(...(o.firstParent ? c.parents.slice(0, 1) : c.parents));
  }
  return d.commits
    .filter((c) => seen.has(c.hash))
    .map((c) => (o.firstParent ? { ...c, parents: c.parents.slice(0, 1) } : c));
}

function reset(): void {
  if (!data) return;
  generation++;
  offset = 0;
  visible = select(data, options);
  toWebview({ type: 'reset', generation, repo: data.repo, refs: data.refs, options, stashes: data.stashes });
}

async function onMessage(m: WebviewToHost): Promise<void> {
  sent.push(m);
  switch (m.type) {
    case 'ready': {
      toWebview({ type: 'init', theme });
      data = (await (await fetch(`data/${repo}.json`)).json()) as PlaygroundData;
      if (m.options) options = { ...m.options, ...queried };
      reset();
      break;
    }
    case 'setOptions': {
      // Like the host: showing or hiding stash rows reloads nothing.
      const reload = m.options.firstParent !== options.firstParent || String(m.options.refs) !== String(options.refs);
      options = m.options;
      if (reload) reset();
      break;
    }
    case 'loadMore': {
      if (!data) return;
      const commits = visible.slice(offset, offset + m.count);
      offset += commits.length;
      toWebview({ type: 'commits', generation, commits, done: offset >= visible.length });
      if (openPopover === 'filter' && offset === commits.length) {
        setTimeout(() => {
          toWebview({ type: 'simulate', action: { kind: 'click', selector: '.ref-filter-button' } });
        }, 50);
      }
      if (selectRow !== null && offset === commits.length) {
        setTimeout(() => {
          toWebview({ type: 'simulate', action: { kind: 'clickRow', index: Number(selectRow) } });
        }, 50);
      }
      if (busy !== null && offset === commits.length) toWebview({ type: 'busy', label: busy });
      if (bannerState !== null && offset === commits.length)
        for (const [operation, leftover] of repoStates(bannerState, data))
          toWebview({ type: 'repoState', operation, leftover });
      if (menuAt !== null && offset === commits.length) {
        setTimeout(() => {
          toWebview({ type: 'simulate', action: { kind: 'contextMenu', selector: menuAt } });
          document.body.classList.add('vscode-context-menu-visible');
        }, 150);
      }
      break;
    }
    case 'select': {
      const details = data?.details[m.hash];
      if (details) toWebview({ type: 'details', generation, details });
      break;
    }
    default:
      break;
  }
}

/** repoState messages that bring the banner into `state`, from the scenario's commits and refs. */
function repoStates(state: string, d: PlaygroundData): [OperationState | undefined, Leftover | undefined][] {
  const at = (short: string) => d.refs.refs.find((r) => r.short === short)?.hash ?? d.commits[0]!.hash;
  const applying = d.commits.find((c) => c.subject === 'Search UI')?.hash ?? d.commits[1]!.hash;
  const stash = { hash: d.stashes[0]?.hash ?? d.commits[0]!.hash, index: 0 };
  const rebase: OperationState = {
    kind: 'rebase',
    branch: 'feature/search',
    onto: at('main'),
    step: { current: 2, total: 4 },
    applying,
    conflicts: ['feature_search.txt', 'src/ranking.ts'],
    conflictCount: 2,
    autostash: true,
  };
  const resolved = { conflicts: [], conflictCount: 0 };
  const merge: OperationState = {
    ...rebase,
    kind: 'merge',
    branch: 'main',
    onto: undefined,
    step: undefined,
    applying: at('feature/login'),
    conflicts: ['main.txt'],
    conflictCount: 1,
  };
  const pick: OperationState = { ...merge, kind: 'cherryPick', applying, autostash: false };
  const states: Record<string, [OperationState | undefined, Leftover | undefined][]> = {
    rebase: [[rebase, undefined]],
    rebaseResolved: [
      [rebase, undefined],
      [{ ...rebase, ...resolved }, undefined],
    ],
    rebaseStopped: [[{ ...rebase, ...resolved }, undefined]],
    merge: [[merge, undefined]],
    mergeResolved: [
      [merge, undefined],
      [{ ...merge, ...resolved }, undefined],
    ],
    sequencer: [[pick, { kind: 'pendingStash', stash, operation: 'cherry pick' }]],
    leftover: [[undefined, { kind: 'restoreConflicted', stash, files: ['src/lexer.ts'] }]],
    leftoverResolved: [[undefined, { kind: 'restoreConflicted', stash, files: [] }]],
    pending: [[undefined, { kind: 'pendingStash', stash, operation: 'cherry pick' }]],
    conflicts: [[undefined, { kind: 'unmerged', files: ['a.txt', 'b.txt'], count: 2, autostash: stash }]],
  };
  return states[state] ?? [];
}

Object.assign(window, {
  __strataSent: sent,
  acquireVsCodeApi: () => {
    let state: unknown;
    return {
      postMessage(m: WebviewToHost) {
        void onMessage(m);
      },
      getState: () => state,
      setState: (s: unknown) => {
        state = s;
      },
    };
  },
});
